from lib import *
recs=[]
recs.append(R(6530550,"بچوں کے لیے قوس قزح پھلوں کی پلیٹر","ایک فوری، آسان اور رنگ برنگی ترکیب جو کوئی بھی بنا سکتا ہے! اسے ناشتے، اسنیک یا میٹھے کے طور پر آزمائیں۔","25",None,
["8 اونس ونیلا یونانی دہی (100 کیلوریز)","1 کھانے کا چمچ چیا سیڈز","1/8 چائے کا چمچ پسی ہوئی دار چینی","4 کپ پوری اسٹرابیریاں (ڈنٹھل ہٹائے ہوئے)","4 کپ خربوزہ (کینٹالوپ) (چکور ٹکڑوں میں کٹا ہوا)","1 تازہ انناس (چھلا ہوا، درمیانی ڈنٹھل نکلا ہوا اور چکور ٹکڑوں میں کٹا ہوا (تقریباً 4 کپ))","3 کپ ہرے انگور","4 کپ بلیو بیریز","3 کپ لال انگور","3 کپ بلیک بیریز"],
["دہی اور چیا سیڈز کو ملا لیں۔ رات بھر فریج میں رکھیں۔ 1/8 چائے کا چمچ دار چینی ملا دیں۔","ایک بہت بڑی پلیٹر پر اسٹرابیریاں سب سے اوپر کی قطار میں رکھیں تاکہ قوس قزح کے نمونے کا اوپری حصہ بن جائے۔","خربوزے کے ٹکڑے اسٹرابیریوں کے نیچے دوسری قطار کے طور پر رکھیں۔ یہی عمل انناس کے ساتھ جاری رکھیں، بلیک بیریز تک، تاکہ قوس قزح کا نمونہ بن جائے۔"]))
recs.append(R(6531377,"کوریائی بی بی کیو سے متاثر بیکڈ سالمن","اس سالمن پر لگی کوریائی بی بی کیو سے متاثر ساس میں میٹھے، نمکین، کھٹے اور مسالے دار ذائقوں کا مثالی توازن ہے۔ مٹھاس قدرتی طور پر پھل سے آتی ہے، اضافی چینی سے نہیں۔ آپ یہ ساس چکن پر بھی استعمال کر سکتے ہیں: بغیر ہڈی اور بغیر کھال کی چکن رانوں کو ساس کے بغیر 15 منٹ بیک کریں، پھر ساس لگائیں اور مزید 15 منٹ بیک کریں، یا جب تک اندر تک پک نہ جائے۔","4","1 فلیٹ",
["4 (6 اونس) فلیٹس درمیانی کٹ کی کھال والی ساکی آئی سالمن","2 کھانے کے چمچ بغیر چینی اضافے کا کیچپ","1 کھانے کا چمچ پھل سے میٹھا کیا ہوا خوبانی کا جام","1 کھانے کا چمچ کم سوڈیم والی تماری یا سویا ساس","2 چائے کے چمچ رائس سرکہ","1/4 چائے کا چمچ ہاٹ ساس","1 چائے کا چمچ تل"],
["اوون کو 400° F پر پہلے سے گرم کریں۔ ایک بڑی کناروں والی بیکنگ شیٹ پر پارچمنٹ پیپر بچھا دیں۔","سالمن کو کھال والی طرف نیچے رکھ کر بیکنگ شیٹ پر رکھیں۔","ایک چھوٹے پیالے میں کیچپ، جام، تماری، سرکہ اور ہاٹ پیپر ساس ملا دیں۔ چمچ کی پشت سے مرکب کو ہر فلیٹ کی اوپری سطح پر ہلکا سا لگا دیں۔ تل چھڑکیں۔","سالمن کے ریشے الگ ہونے اور اندر تک پکنے تک بیک کریں (اندرونی درجہ حرارت کم از کم 145°F ہو)، تقریباً 16 منٹ۔ پیش کریں۔"]))
recs.append(R(6536371,"جھینگا سوتے پالک، گریپ ٹماٹر اور روسٹ کیے ہوئے لال آلوؤں کے ساتھ","یہ فوری اور مزیدار جھینگے کی ڈش کم کاربوہائیڈریٹ اور کم چکنائی والے کھانے کے انداز کی پیروی کرتی ہے، یعنی یہ ان لوگوں کے لیے اچھا انتخاب ہے جو اپنے بلڈ پریشر کا خیال رکھتے ہیں۔ رسیلے جھینگوں کو تازہ پالک، میٹھے گریپ ٹماٹروں اور کرکرے روسٹ کیے ہوئے لال آلوؤں کے ساتھ سوتے کیا جاتا ہے، جس سے ذائقوں اور ساخت کا ہم آہنگ امتزاج بنتا ہے۔ یہ ایک دل بھرنے والی اور لذیذ ڈش ہے جو ہفتے کی رات کے کھانے کے لیے بہترین ہے۔","4","1 کپ جھینگے اور سبزیاں، ½ کپ آلو",
["16 اونس بیبی لال آلو","1 کھانے کا چمچ زیتون کا تیل","1/2 چائے کا چمچ اطالوی مسالا","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","1 پائنٹ گریپ ٹماٹر (آدھے کٹے ہوئے)","2 جوے لہسن (باریک کٹے ہوئے)","1 1/2 پاؤنڈ بڑے جھینگے (چھلے ہوئے اور آنت نکلی ہوئی)","1/4 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس","5 اونس بیبی پالک","1 1/2 اونس پارمیزان پنیر (باریک کدوکش کیا ہوا)","1/2 کپ تازہ تلسی کے پتے (باریک لمبی پٹیوں میں کٹے ہوئے)"],
["اوون کو 425 ڈگری F پر پہلے سے گرم کریں۔ بیبی لال آلوؤں کو ان کے سائز کے مطابق آدھا یا چار ٹکڑوں میں کاٹ لیں۔ انہیں بیکنگ شیٹ پر 2 چائے کے چمچ زیتون کے تیل، اطالوی مسالے، نمک اور کالی مرچ کے ساتھ ملا دیں۔","اوون میں 20–25 منٹ روسٹ کریں، آدھے وقت پر پلٹ دیں، جب تک سنہری اور نرم نہ ہو جائیں۔","فرائنگ پین کو درمیانی آنچ پر گرم کریں۔ باقی زیتون کا تیل اور گریپ ٹماٹر پین میں ڈالیں۔ کبھی کبھار ہلاتے ہوئے 3–4 منٹ پکائیں، یا جب تک ٹماٹر نرم نہ ہو جائیں اور اپنا کچھ رس نہ چھوڑ دیں","لہسن، جھینگے اور کٹی ہوئی لال مرچ پین میں ڈالیں۔ جھینگوں کو ہر طرف 1–2 منٹ سوتے کریں، یا جب تک مبہم سفید ہو کر اندر تک نہ پک جائیں۔","پالک کو مٹھی بھر کر کے پین میں ڈالیں، ہر بار ڈالنے کے بعد ہلائیں تاکہ وہ مرجھا جائے۔","آنچ کو کم کر دیں اور آدھا کدوکش کیا ہوا پارمیزان پنیر پین کے اجزاء پر چھڑکیں۔ ملانے کے لیے ہلائیں اور پنیر کو ذرا پگھلنے دیں۔","جھینگے، سوتے کی ہوئی سبزیاں اور پالک پلیٹوں میں تقسیم کریں۔ بچائے ہوئے پارمیزان پنیر اور تلسی کی پٹیوں سے سجائیں۔ روسٹ کیے ہوئے لال آلوؤں کے ساتھ پیش کریں۔"]))
recs.append(R(6536789,"بروکلی پیاز لیٹکس","یہ کم کاربوہائیڈریٹ والے لیٹکس روایتی آلو کی جگہ بروکلی استعمال کرتے ہیں۔ ان میں پوٹاشیم بھی کم ہے، اس لیے یہ گردوں کی صحت کے لیے کم پوٹاشیم والی غذا پر عمل کرنے والوں کے لیے بہترین متبادل ہیں۔","4","1 لیٹکے",
["3 کپ تازہ یا منجمد کٹے ہوئے بروکلی کے پھولے","1/2 کپ چکور کٹی ہوئی پیاز","2 عدد انڈے","2 کھانے کے چمچ میدہ (آل پرپز آٹا)","2 کھانے کے چمچ زیتون کا تیل"],
["چکور کٹی بروکلی کو تھوڑے سے پانی میں 5 منٹ ابالیں، پھر اچھی طرح پانی نتھار لیں۔","انڈے ایک درمیانے پیالے میں توڑ کر پھینٹ لیں۔ آٹا ڈال کر اچھی طرح ملائیں۔ بروکلی اور پیاز ڈال کر آٹے/انڈے کے مرکب میں اچھی طرح ملنے تک ہلائیں۔","ایک فرائنگ پین میں زیتون کا تیل درمیانی تیز آنچ پر گرم کریں۔ مرکب کو چمچ بھر بھر کر گرم تیل میں ڈالیں، 4 برابر حصے بناتے ہوئے۔ اسپیچولا سے چپٹا کریں اور دونوں طرف سنہری بھورا ہونے تک پکائیں (ہر طرف تقریباً 3-4 منٹ)۔","لیٹکس کو پین سے نکالیں اور اضافی تیل جذب کرنے کے لیے کاغذی تولیے پر رکھیں۔ گرم پیش کریں۔"]))
recs.append(R(6536966,"بیسن چیلا","چنے کے آٹے اور رنگ برنگی سبزیوں سے بنا بیسن چیلا ایک مقبول نمکین پین کیک ہے جسے بہت سے ہندوستانی گھروں میں پسند کیا جاتا ہے۔ اس کا ہلکا سا گری دار ذائقہ، کرکرے کنارے اور نرم درمیانی حصہ اسے مزیدار ناشتہ یا ہلکا کھانا بناتے ہیں، جبکہ چنے کا آٹا پروٹین اور فائبر فراہم کرتا ہے۔","1","1 پین کیک",
["1/4 کپ چنے کا آٹا (بیسن)","1/4 کپ پانی","2 کھانے کے چمچ پیلی پیاز (باریک کٹی ہوئی)","2 کھانے کے چمچ پالک (باریک کٹی ہوئی)","2 کھانے کے چمچ شملہ مرچ (باریک کٹی ہوئی)","2 کھانے کے چمچ زکینی (کدوکش کی ہوئی)","1/4 چائے کا چمچ پسا ہوا زیرہ","1/4 چائے کا چمچ پسا ہوا دھنیا","1/16 چائے کا چمچ ہلدی","1/16 چائے کا چمچ لال مرچ پاؤڈر (چلی پاؤڈر)","1/16 چائے کا چمچ نمک","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1 کھانے کا چمچ سادہ بغیر چکنائی والا یونانی دہی"],
["ایک پیالے میں بیسن، پانی اور مسالوں کو ہموار ہونے تک پھینٹ لیں۔","سبزیاں ملا دیں۔ ڈھانپ کر 5-10 منٹ کے لیے ایک طرف رکھ دیں۔ دوبارہ اچھی طرح ملا لیں۔","ایک نان اسٹک فرائنگ پین کو درمیانی آنچ پر گرم کریں اور اس پر ہلکا سا کوکنگ اسپرے کریں۔","آمیزہ پین میں ڈالیں، اسے آہستگی سے برابر پھیلائیں اور شکل کو گول کر کے 6 انچ کا پتلا پین کیک بنا لیں۔","ہر طرف 2-3 منٹ پکائیں، جب تک ہلکا بھورا نہ ہو جائے اور اندر تک پک نہ جائے۔","گرم پیش کریں اور ساتھ میں 1 کھانے کا چمچ سادہ یونانی دہی ڈبونے کے لیے رکھیں۔"]))
recs.append(R(6536985,"نیوٹریشنل ایسٹ","4 کھانے کے چمچ نیوٹریشنل ایسٹ کی غذائی معلومات۔","1","4 کھانے کے چمچ",["4 کھانے کے چمچ نیوٹریشنل ایسٹ"],[]))
recs.append(R(6537876,"کریمی مسلی ہوئی پھول گوبھی","کریمی مسلی ہوئی پھول گوبھی اس وقت کے لیے کم کاربوہائیڈریٹ متبادل ہے جب آپ کا دل مسلے ہوئے آلو کھانے کو چاہے۔ ذیابیطس کے لیے موزوں یہ ترکیب وہ سب کچھ ہے جو آپ ایک کلاسک آرام دہ کھانے سے چاہ سکتے ہیں۔","4","3/4 کپ",
["1 عدد پھول گوبھی (بڑی، پھولوں میں کٹی ہوئی)","1 کھانے کا چمچ بغیر نمک کا مکھن","2 جوے لہسن (باریک کٹے ہوئے)","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","1/4 کپ سادہ بغیر چکنائی والا یونانی دہی"],
["پھول گوبھی کے پھولوں کو بھاپ میں یا ابال کر کانٹے سے نرم ہونے تک پکائیں، تقریباً 10–12 منٹ۔","پکی ہوئی پھول گوبھی ایک بڑے پیالے میں ڈالیں۔","ایک چھوٹے پین میں مکھن درمیانی آنچ پر پگھلائیں۔ باریک کٹا لہسن ڈالیں اور 1–2 منٹ سوتے کریں جب تک خوشبو نہ آئے۔","لہسن والا مکھن، نمک اور کالی مرچ پھول گوبھی میں ڈالیں۔","پھول گوبھی میں یونانی دہی ڈالیں۔","ہینڈ بلینڈر سے پھول گوبھی کو ہموار اور کریمی ہونے تک بلینڈ کریں۔"]))
recs.append(R(6538174,"کریمی چکن سیب سلاد","یہ سلاد کم کاربوہائیڈریٹ والا، طاقتور غذا کا خزانہ ہے۔ تیار کرنے میں آسان اور اچھی غذائیت سے بھرپور، چکن سے پروٹین، سیب سے فائبر اور اخروٹ سے صحت بخش چکنائی، یہ ایک فوری ذیابیطس کے لیے موزوں ترکیب ہے جو دوپہر کے کھانے اور پہلے سے تیار کرنے کے لیے بہترین ہے۔ ذائقے اور کرکراہٹ سے بھرپور، آپ یقین نہیں کریں گے کہ یہ کتنا آسان ہے!","8","1/2 کپ",
["2 کپ پکا ہوا چکن بریسٹ (کٹا ہوا)","2 ڈنڈی اجوائن (چکور کٹی ہوئی)","2 ہری پیاز (کٹی ہوئی)","1 درمیانا جونا گولڈ سیب (باریک چکور کٹا ہوا)","3 کھانے کے چمچ اخروٹ (کٹے ہوئے)","1/4 کپ لائٹ مایونیز","1/4 کپ دہی (سادہ، بغیر چکنائی والا)","1/2 لیموں (رس نکالا ہوا)","1/8 چائے کا چمچ کالی مرچ"],
["ایک درمیانے پیالے میں چکن، اجوائن، ہری پیاز، سیب اور اخروٹ ملائیں","ایک چھوٹے پیالے میں مایونیز، دہی، لیموں کا رس اور کالی مرچ پھینٹ کر ملا لیں۔ چکن کے مرکب پر ڈالیں اور آہستگی سے ہلا کر سب پر لگا دیں۔","سلاد کو اپنی پسند کے لیٹس کے پتوں، ڈبل روٹی یا کریکرز پر پیش کریں۔"]))
recs.append(R(6538918,"شکر قندی کا سلاد ہرے دھنیے اور لائم کے ساتھ","ٹیکس-میکس انداز کا یہ سلاد دل بھرنے والا اور پیٹ بھرنے والا ہے اور یقیناً آپ کے ذائقے کی حس کو جگا دے گا۔ یہ ذیابیطس کے لیے موزوں ہے اور آپ کے اگلے ٹیکو منگل کے رات کے کھانے کے لیے سائیڈ ڈش کے طور پر بہترین رہے گا!","6","1 کپ",
["2 بڑی شکر قندیاں (چھلی ہوئی اور کاٹنے کے سائز کے چکور ٹکڑوں میں کٹی ہوئی)","2 کھانے کے چمچ زیتون کا تیل","1 چائے کا چمچ زیرے کے بیج","1/2 چائے کا چمچ اسموکڈ پیپریکا","1/4 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ کالی مرچ","1/4 کپ تازہ ہرا دھنیا (کٹا ہوا)","1 درمیانا لائم (چھلکا اور رس)","1/4 کپ لال پیاز (باریک کٹی ہوئی)","1 درمیانا ایوکاڈو (چکور کٹا ہوا)","1 (15 اونس) ڈبہ کالی پھلیاں (کم سوڈیم والی، پانی نکالی ہوئی اور دھوئی ہوئی)"],
["اوون کو 400 ڈگری F پر پہلے سے گرم کریں۔","ایک بڑے پیالے میں چکور کٹی شکر قندی کو زیتون کے تیل، زیرہ، اسموکڈ پیپریکا، نمک اور کالی مرچ کے ساتھ برابر لگنے تک ملا دیں۔","مسالا لگی شکر قندی کو بیکنگ شیٹ پر ایک تہہ میں پھیلا دیں۔","پہلے سے گرم اوون میں 30 منٹ روسٹ کریں یا جب تک شکر قندی نرم اور ذرا کیریمل نہ ہو جائے، آدھے وقت پر ہلا دیں۔","جب شکر قندی روسٹ ہو رہی ہو، ڈریسنگ تیار کریں۔ لائم کا چھلکا اور رس نکال لیں۔ ایک چھوٹے پیالے میں کٹا ہوا تازہ ہرا دھنیا، لائم کا چھلکا اور لائم کا رس ملائیں۔","جب شکر قندی تیار ہو جائے تو اسے سرونگ باؤل میں منتقل کریں۔","ہرے دھنیے اور لائم کی ڈریسنگ روسٹ کی ہوئی شکر قندی پر ڈالیں۔","باریک کٹی لال پیاز، ایوکاڈو اور کالی پھلیاں پیالے میں ڈالیں۔","سلاد کو آہستگی سے ملائیں تاکہ برابر لگ جائے۔"]))
recs.append(R(6538924,"پھول گوبھی کا تبولہ","تبولہ بحیرہ روم کا ایک روایتی سلاد ہے جو لذیذ جڑی بوٹیوں، تازہ لیموں اور کسکس سے بنایا جاتا ہے۔ ذیابیطس کے لیے موزوں یہ ورژن کم کاربوہائیڈریٹ، اناج سے پاک متبادل کے لیے پھول گوبھی کے چاول استعمال کرتا ہے۔","6","1 کپ",
["1 کپ دبا کر بھرے پارسلے کے پتے","1/4 کپ دبا کر بھرے پودینے کے پتے","1 عدد چھوٹی پھول گوبھی (یا 16 اونس منجمد پھول گوبھی کے چاول) (پتے اور ڈنٹھل ہٹائے ہوئے)","2 درمیانے روما (پلم) ٹماٹر (بیج نکلے ہوئے اور چکور کٹے ہوئے)","2 کھانے کے چمچ زیتون کا تیل","3 کھانے کے چمچ لیموں کا رس (تازہ نچوڑا ہوا)","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["پارسلے اور پودینے کے پتے باریک کاٹ لیں (یا فوڈ پروسیسر میں پیس لیں) اور ایک بڑے پیالے میں ڈالیں۔","پھول گوبھی کو باکس گریٹر سے کدوکش کریں اور پارسلے اور پودینے کے ساتھ ملا لیں۔","چکور کٹے ٹماٹر ڈالیں اور سلاد میں ملا دیں۔","سلاد پر زیتون کا تیل اور لیموں کا رس ڈالیں، اور نمک (اختیاری) اور کالی مرچ چھڑکیں۔ ملا کر سب پر لگا دیں۔","ڈھانپ دیں اور تبولہ کو پیش کرنے سے پہلے 30 منٹ میرینیٹ ہونے دیں۔"]))
recs.append(R(6539733,"آسان مشرق وسطیٰ کی ہری پھلیاں","یہ ڈش لبنانی ڈش لوبیہ سے متاثر ہے۔ یہ بس ہری پھلیاں اور گریپ ٹماٹر ہیں جنہیں ایکسٹرا ورجن زیتون کے تیل کی بالکل مناسب مقدار کے ساتھ پکایا جاتا ہے اور دار چینی اور سمندری نمک کا ذائقہ دیا جاتا ہے۔ یہ جلدی تیار ہو جاتی ہے اور آپ کے باقی کھانے کے پکتے وقت آسانی سے بنائی جا سکتی ہے۔ ہفتے کی رات کے فوری اور آسان کھانے کے لیے اسے پروٹین کی کسی سادہ ڈش، جیسے Balsamic Glazed Salmon، کے ساتھ ملائیں۔\n\nیہ ترکیب اور مزید The Clean & Simple Diabetes Cookbook میں ملاحظہ کریں، مصنفہ Jackie Newgent, RDN, CDN","2","1 1/2 کپ",
["2 چائے کے چمچ ایکسٹرا ورجن زیتون کا تیل","8 اونس تازہ ہری پھلیاں (ڈنٹھل کے سرے کٹے ہوئے)","1 کپ گریپ ٹماٹر","1/4 چائے کا چمچ پسی ہوئی دار چینی","1/8 چائے کا چمچ نمک"],
["ایک بڑے نان اسٹک فرائنگ پین میں تیل درمیانی آنچ پر گرم کریں۔ ہری پھلیاں اور ٹماٹر ڈالیں، ڈھانپ دیں اور اس وقت تک پکائیں جب تک ہری پھلیاں نرم لیکن کرکری نہ ہو جائیں اور ٹماٹر پوری طرح نرم نہ ہو جائیں، تقریباً 10 منٹ۔ پکانے کے دوران چمٹے سے دو تین بار ملا دیں۔","سبزیوں پر دار چینی اور نمک چھڑکیں۔ ملا کر یکجا کریں، پھر پیش کریں۔"]))
recs.append(R(6540545,"سالم گندم کے پالک پراٹھے","پراٹھا ایک قسم کی چپٹی روٹی ہے جس کی ابتدا بھارت کے شمالی حصے میں ہوئی، جہاں یہ آج بھی مقبول ہے۔ یہ روایتی ہندوستانی ناشتے کا حصہ ہے، لیکن دوپہر یا رات کے کھانے کے ساتھ بھی پیش کیا جا سکتا ہے۔","8","1 پراٹھا",
["2/3 کپ پانی","2 کپ اور 1 کھانے کا چمچ سالم گندم کا پیسٹری آٹا (تقسیم شدہ)","1 چائے کا چمچ پسا ہوا زیرہ","1/2 چائے کا چمچ امچور (آم) پاؤڈر","1/2 چائے کا چمچ باریک سمندری نمک (تقسیم کر کے استعمال کریں)","1 کپ (دبا کر بھری) بیبی پالک (کٹی ہوئی)","1 عدد ہری مرچ (بیج نکال کر پھینکے ہوئے، باریک کٹی ہوئی)","1 کھانے کا چمچ تازہ ادرک (کدوکش کیا ہوا)","1 چائے کا چمچ اجوائن کے بیج","3 چائے کے چمچ سورج مکھی کا تیل (تقسیم کر کے استعمال کریں)"],
["ایک بھاری پیندے والے پین میں درمیانی تیز آنچ پر 1 چائے کا چمچ تیل گرم کریں۔ اجوائن کے بیج، ادرک اور ہری مرچ ڈالیں۔ بار بار ہلاتے ہوئے تقریباً 1 منٹ پکائیں۔","پالک اور ¼ چائے کا چمچ نمک ڈالیں۔ 3 منٹ پکائیں، یا جب تک پالک سے نکلنے والی نمی جذب نہ ہو جائے اور تہہ خشک نہ ہو جائے۔ امچور پاؤڈر اور زیرہ ڈال کر اچھی طرح ہلائیں۔ آنچ سے ہٹا لیں۔ ٹھنڈا ہونے کے لیے ایک طرف رکھ دیں۔","پراٹھے کا آٹا بنانے کے لیے: 2 کپ آٹا اور باقی ¼ چائے کا چمچ نمک ایک اتھلی ڈش میں ملائیں۔ پالک کا مرکب آٹے کے مرکب میں ڈالیں۔ تھوڑا تھوڑا کر کے پانی ڈالیں تاکہ ہموار آٹا گندھ جائے (پیزا آٹے کی طرح)۔ آٹے کو ہموار ہونے تک گوندھیں۔ شیشے کے پیالے میں منتقل کریں۔ نم تولیے سے ڈھانپ دیں۔ کمرے کے درجہ حرارت پر 30 منٹ سے ایک گھنٹے کے لیے ایک طرف رکھ دیں۔","آرام کے وقت کے بعد آٹے کو ایک بار پھر گوندھیں۔ 8 گولے بنا لیں۔ اپنی کام کی سطح پر باقی 1 کھانے کا چمچ آٹا ہلکا سا چھڑکیں۔ بیلن کی مدد سے ہر آٹے کے گولے کو چپٹا کریں تاکہ اس کا قطر 6 انچ ہو جائے۔","کاسٹ آئرن توا یا چپٹے فرائنگ پین کو درمیانی تیز آنچ پر پہلے سے گرم کریں۔ آٹے کا ایک ٹکڑا پین میں رکھیں۔ تقریباً 1 منٹ پکائیں، یا جب تک بلبلے بننا شروع نہ ہو جائیں۔","پراٹھے کو پلٹیں۔ باقی تیل میں سے ¼ چائے کا چمچ لگا دیں۔ ہر طرف تقریباً 3–4 منٹ پکاتے رہیں، ضرورت کے مطابق پلٹتے ہوئے، جب تک دونوں طرف کنارے بھورے نہ ہو جائیں۔ چپٹے اسپیچولا سے پکتے وقت پراٹھے کے درمیان کو دباتے رہیں تاکہ وہ برابر پکے۔","پین سے اتار لیں۔ باقی آٹے کے ٹکڑوں اور باقی تیل کے ساتھ پکانے کا عمل دہرائیں۔ گرم پیش کریں۔"]))
recs.append(R(6541626,"کیپریزے کباب","یہ آسان اسٹارٹر گرمیوں کے لیے بہترین ہے اور باغ کے تازہ اجزاء استعمال کرتا ہے۔ یہ کباب ذائقے سے بھرپور اور کم کاربوہائیڈریٹ والے ہیں۔ یہ سرونگ پلیٹر پر بھی بہت خوبصورت لگتے ہیں اور یقیناً مہمانوں کو متاثر کریں گے!","18","1 کباب",
["18 چھوٹی بانس کی سیخیں","18 پتے تازہ تلسی (آدھے تہہ کیے ہوئے)","18 درمیانے گریپ ٹماٹر","18 عدد تازہ موزاریلا کے گولے (ہر ایک 1/4 اونس)","1 کھانے کا چمچ زیتون کا تیل","1 1/2 کھانے کے چمچ بالسامک سرکہ"],
["ہر بانس کی سیخ پر 1 گریپ ٹماٹر، 1 تلسی کا پتا اور 1 موزاریلا کا گولا رکھیں۔ 18 کبابوں کے لیے یہ عمل دہرائیں۔ کبابوں کو سرونگ پلیٹر پر رکھیں۔","ایک چھوٹے پیالے میں زیتون کا تیل اور بالسامک سرکہ پھینٹ کر ملا لیں۔ پیش کرنے سے ذرا پہلے ڈریسنگ کبابوں پر ڈالیں تاکہ برابر لگ جائے۔"]))
